python3 -I - <<'EOF'
import pathlib, re
p = pathlib.Path('reports/spec2-m1-close.md'); rep = p.read_text()
rep = rep.replace("Jumeaux : `invA` (`:170`), `invB` (`:177`)", "Jumeaux : `invA` (`EncapTraces.lean:170`), `invB` (`EncapTraces.lean:177`)")
p.write_text(rep)
files = {f.name: f.read_text().split('\n') for f in pathlib.Path('Ern/Concurrency').glob('*.lean')}
def sect(a, b):
    i = rep.index(a); j = rep.index(b, i); return rep[i:j]
for title, end, default in [('## A.4', '## A.5', 'EncapTraces.lean'), ('## B.5', 'Lemmes de la Spec 1 importés', 'Preservation.lean'), ('## B.3', 'Couverture du corpus', None), ('## B.1', '## B.2', None)]:
    for row in sect(title, end).split('\n'):
        cur = default
        for m in re.finditer(r"`([A-Za-z_][A-Za-z0-9_.'?]*)`\s*\(`(?:([A-Za-z]+\.lean))?:(\d+)`", row):
            name, f, ln = m.group(1), m.group(2), int(m.group(3))
            if f: cur = f
            if cur is None: print('NOFILE', name, ln); continue
            line = files[cur][ln-1]
            if name.split('.')[-1] not in line: print('MISMATCH', title, name, cur, ln, '|', line[:70])
print('done')
EOF

